#!/usr/bin/env node
// Build decks: node scripts/build.js [all | 06 | 06 12 ...]
// For each decks/NN-slug/deck.js writes deck.pptx, deck.html and notes.md, runs the
// series checks, then regenerates decks/manifest.md and decks/index.html.

const fs = require("fs");
const path = require("path");
const { buildDeck } = require("../decks/_engine/kit");
const { renderPptx } = require("../decks/_engine/render-pptx");
const { renderHtml } = require("../decks/_engine/render-html");
const { PALETTES } = require("../decks/_engine/tokens");
const { writeGallery } = require("./gallery");

const ROOT = path.join(__dirname, "..", "decks");

function deckDirs() {
  return fs.readdirSync(ROOT).filter(d => /^\d\d-/.test(d) && fs.existsSync(path.join(ROOT, d, "deck.js"))).sort();
}

function load(dir) {
  const file = path.join(ROOT, dir, "deck.js");
  delete require.cache[require.resolve(file)];
  return require(file);
}

// ---- checks ------------------------------------------------------------------------
function lum(hex) {
  const c = [0, 2, 4].map(i => parseInt(hex.slice(i, i + 2), 16) / 255).map(v => (v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
function contrast(a, b) { const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p); return (x + 0.05) / (y + 0.05); }
// US English: Baylor is an American department.
const UK = /\b(\w+(?:isation|ised|ising|ise)s?|colours?|behaviours?|centres?|centred|maths|programmes?|practise[sd]?|favour\w*|honour\w*|labour\w*|organis\w*|analys(?:e|ed|es|ing)|metres?|litres?|defence|travelled|travelling|modelling|whilst|amongst)\b/i;
const UK_OK = /^(exercise[sd]?|exercising|otherwise|promise[sd]?|surprise[sd]?|precise|concise|advise[sd]?|revise[sd]?|expertise|rise[s]?|raise[sd]?|arise[s]?|noise|wise|likewise|praise[sd]?|franchise|merchandise|premise[s]?|compromise[sd]?|enterprise[s]?|supervise[sd]?|disguise[sd]?|demise|improvise[sd]?|devise[sd]?|despise[sd]?|excise|comprise[sd]?|bruise[sd]?|cruise[sd]?|poise[sd]?|guise|treatise|paradise|reprise)$/i;
const words = s => (s.match(/[A-Za-z0-9%][^\s]*/g) || []).length;

function check(deck) {
  const errs = [], warns = [];
  const m = deck.meta;
  const ids = new Set((m.sources || []).map(s => s.id));
  const used = new Set();
  let total = 0;
  for (const req of ["num", "slug", "title", "category", "palette", "hero", "question", "sources", "compose"]) if (m[req] == null) errs.push(`meta.${req} missing`);
  if (m.hero && (!m.hero.layout || !m.hero.concept)) errs.push("meta.hero needs layout and concept");
  deck.slides.forEach((sl, i) => {
    total += sl.time || 0;
    if (!sl.notes || words(sl.notes) < 25) errs.push(`slide ${i + 1}: talking points too thin`);
    sl.scene.refs.forEach(r => { used.add(r); if (!ids.has(r)) errs.push(`slide ${i + 1}: unknown source "${r}"`); });
    let bodyWords = 0;
    for (const it of sl.scene.items) {
      if (it.t !== "text") continue;
      const txt = it.runs.map(r => r.t).join("");
      if (!["source", "label", "figure"].includes(it.role) && !/^\s*\d{1,2}\s*$/.test(txt)) bodyWords += words(txt);
      const uk = txt.match(UK);
      if (uk && !UK_OK.test(uk[0])) errs.push(`slide ${i + 1}: British spelling "${uk[0]}" (use US English)`);
      for (const r of it.runs) {
        const col = r.color || it.color;
        const size = r.size || it.size;
        const need = size >= 24 || (size >= 18.5 && /Bold|SemiBold/.test(it.font)) ? 3 : 4.5;
        const cr = contrast(col, sl.scene.P.bg);
        if (cr < need) errs.push(`slide ${i + 1}: "${r.t.slice(0, 24)}" contrast ${cr.toFixed(2)} < ${need}`);
        if (size < 11) errs.push(`slide ${i + 1}: "${r.t.slice(0, 24)}" is ${size}pt, below the 11pt floor`);
      }
      if (it.x < 0 || it.y < 0 || it.x + it.w > 13.34 || it.y + it.h > 7.51) errs.push(`slide ${i + 1}: text box off the slide`);
    }
    if (bodyWords > 45) errs.push(`slide ${i + 1}: ${bodyWords} words on the slide (limit 45, aim for 35)`);
    else if (bodyWords > 35) warns.push(`slide ${i + 1}: ${bodyWords} words on the slide (aim for 35)`);
    const ukn = String(sl.notes || "").match(UK);
    if (ukn && !UK_OK.test(ukn[0])) warns.push(`slide ${i + 1} notes: British spelling "${ukn[0]}"`);
  });
  if (total < 255 || total > 315) errs.push(`timing totals ${total}s; target ~285s (4:45)`);
  ids.forEach(id => { if (!used.has(id)) warns.push(`source "${id}" listed but not cited on any slide`); });
  (m.sources || []).forEach(s => { if (!s.cite || s.cite.length < 30) errs.push(`source "${s.id}" needs a full citation`); });
  return { errs, warns, total };
}

// ---- notes.md -------------------------------------------------------------------------
function notesMd(deck) {
  const m = deck.meta;
  const fmt = s => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
  let t = 0;
  let out = `# ${m.title}\n\n5 Slides in 5 Minutes · ${m.category} · Baylor Athletics Applied Performance\n\n`;
  out += `**One idea:** ${m.oneIdea || ""}\n\n**Discussion question:** ${m.question}\n\n`;
  out += `## Talking points\n\n`;
  deck.slides.forEach((sl, i) => {
    const refs = [...sl.scene.refs];
    out += `### ${i + 1}. ${sl.roleName} (${fmt(t)}–${fmt(t + (sl.time || 0))}, ~${sl.time}s)\n\n${sl.notes.trim()}\n\n`;
    if (refs.length) out += `_Sources on this slide: ${refs.map(r => `[${r}]`).join(", ")}_\n\n`;
    t += sl.time || 0;
  });
  out += `Total: about ${fmt(t)}.\n\n## Sources\n\n`;
  for (const s of m.sources) {
    out += `- **[${s.id}]** ${s.cite}${s.url ? ` <${s.url}>` : ""}${s.grade ? ` _Evidence: ${s.grade}._` : ""}${s.found ? ` _Found via: ${s.found}._` : ""}\n`;
    if (s.supports) out += `  - Supports: ${s.supports}\n`;
  }
  if (m.caveats) out += `\n## Caveats for the presenter\n\n${m.caveats.trim()}\n`;
  return out;
}

// ---- manifest --------------------------------------------------------------------------
function writeManifest(metas) {
  const comp = m => (m.compose ? `${m.compose.hook} / ${m.compose.takeaway} / ${m.compose.align}` : "");
  const rows = metas.map(m => `| ${String(m.num).padStart(2, "0")} | ${m.title} | ${m.category} | ${m.hero.layout} | ${m.hero.concept} | ${m.palette} (${PALETTES[m.palette].name}) | ${comp(m)} |`);
  const pairs = new Map();
  const dupes = [];
  metas.forEach(m => {
    const k = `${m.hero.layout}|${m.palette}`;
    if (pairs.has(k)) dupes.push(`${pairs.get(k)} and ${m.num} share ${k}`);
    pairs.set(k, m.num);
  });
  const layouts = new Map();
  metas.forEach(m => { if (layouts.has(m.hero.layout)) dupes.push(`${layouts.get(m.hero.layout)} and ${m.num} share hero layout ${m.hero.layout}`); layouts.set(m.hero.layout, m.num); });
  const md = `# 5 Slides in 5 Minutes: deck manifest\n\nGenerated by \`scripts/build.js\`. One row per deck. The hero is the Insight slide's visual (slide 3). Uniqueness rule: no two decks share a hero layout, so no two share a hero layout + palette pair.\n\n${metas.length} decks · ${dupes.length ? `**DUPLICATES: ${dupes.join("; ")}**` : "no duplicate hero layouts or layout + palette pairs"}\n\n| # | Topic | Category | Hero layout | Hero concept | Palette | Hook / takeaway / alignment |\n|---|---|---|---|---|---|---|\n${rows.join("\n")}\n`;
  fs.writeFileSync(path.join(ROOT, "manifest.md"), md);
  return dupes;
}

// ---- main ------------------------------------------------------------------------------
async function main() {
  const args = process.argv.slice(2);
  const all = deckDirs();
  const targets = !args.length || args[0] === "all" ? all : all.filter(d => args.some(a => d.startsWith(String(a).padStart(2, "0"))));
  let failed = 0;
  for (const dir of targets) {
    const out = path.join(ROOT, dir);
    try {
      const deck = buildDeck(load(dir));
      const { errs, warns, total } = check(deck);
