// alignment = left.

module.exports = {
  num: 1,
  slug: "post-practice-cognitive-deficit",
  title: "Post-Practice Cognitive Deficit",
  category: "Contextual Engineering & Education Delivery",
  palette: "night",
  hero: { layout: "dip-recovery-curve", concept: "One line of thinking sharpness that dips briefly at the end of hard practice and comes back within minutes; a second, dashed line stays low when the athlete is dehydrated or short on sleep" },
  compose: { hook: "small-figure-field", takeaway: "question-right", align: "left" },
  oneIdea: "Hard practice doesn't fog the brain for long. Dehydration and short sleep do, so refuel first, then teach.",
  question: "What do we try to teach in the first five minutes after practice?",
  caveats: `The topic is often pitched as "after hard exercise, working memory and processing speed drop significantly." The research doesn't support that as a general rule. Across 79 studies, a single bout of exercise gave thinking a small boost on average, including right after (Chang et al. 2012). After very hard exercise the results are mixed; in Sudo et al.'s review, impairments were only reported when testing happened within about six minutes. Present the six minutes as what that review observed, not as a measured threshold. Those studies used short lab bouts (mostly 5-60 minutes of cycling or running in comfortable rooms), not a two-and-a-half-hour practice in Texas heat; long, hot sessions are less studied, and dehydration is the likeliest reason they would differ. The dehydration and sleep findings come from lab studies in mostly non-athlete adults. The curve on slide 3 is a drawn shape, labeled as illustrative. Don't promise a number of minutes to wait; the practical rule is water, food and cooling down first.`,
  sources: [
    { id: "chang2012", cite: "Chang YK, Labban JD, Gapin JI, Etnier JL. The effects of acute exercise on cognitive performance: a meta-analysis. Brain Res. 2012;1453:87-101. doi:10.1016/j.brainres.2012.02.068", grade: "meta-analysis (79 studies)", found: "external", supports: "Overall effect of a single exercise bout on cognition was small and positive (g = 0.097), including immediately after exercise (g = 0.108)." },
    { id: "sudo2022", cite: "Sudo M, Costello JT, McMorris T, Ando S. The effects of acute high-intensity aerobic exercise on cognitive performance: a structured narrative review. Front Behav Neurosci. 2022;16:957677. doi:10.3389/fnbeh.2022.957677", grade: "structured narrative review of lab studies", found: "external", supports: "Results after high-intensity exercise are mixed; 'no impairments were reported when the timing of cognitive tasks was > 6 min after exercise.'" },
    { id: "wittbrodt2018", cite: "Wittbrodt MT, Millard-Stafford M. Dehydration impairs cognitive performance: a meta-analysis. Med Sci Sports Exerc. 2018;50(11):2360-2368. doi:10.1249/MSS.0000000000001682", grade: "meta-analysis (33 studies)", found: "external", supports: "Dehydration impairs attention, executive function and motor coordination; impairment was greater in studies reporting more than 2% body mass loss." },
    { id: "fullagar2015", cite: "Fullagar HHK, Skorski S, Duffield R, Hammes D, Coutts AJ, Meyer T. Sleep and athletic performance: the effects of sleep loss on exercise performance, and physiological and cognitive responses to exercise. Sports Med. 2015;45(2):161-186. doi:10.1007/s40279-014-0260-0", grade: "narrative review", found: "Zotero", supports: "Section 4.3: when sleep is cut to under 7 hours, healthy adults do worse on tests of alertness, reaction time and memory." },
